<?php session_start(); require_once __DIR__ . '/db.php';  if ($_SERVER['REQUEST_METHOD'] === 'POST') {     $username = trim($_POST['username'] ?? '');     $password = $_POST['password'] ?? '';      $stmt = $pdo->prepare('SELECT admin_id, username, password_hash FROM admins WHERE username = ?');     $stmt->execute([$username]);     $admin = $stmt->fetch();      if ($admin && password_verify($password, $admin['password_hash'])) {         session_regenerate_id(true);         $_SESSION['admin_id'] = (int)$admin['admin_id'];  $_SESSION['admin_username'] = $admin['username'];         header('Location: dashboard.php');         exit;     }     $error = 'Invalid username or password.'; } ?> <!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Admin login</title> <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="css/style.css"></head> <body><main class="container form-panel"> <h1>Administrator login</h1> <?php if (!empty($error)): ?><p class="text-danger" role="alert"><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></p><?php endif; ?> <form method="post">   <div class="mb-3"><label for="username" class="form-label">Username</label><input id="username" name="username" class="form-control" required></div>   <div class="mb-3"><label for="password" class="form-label">Password</label><input id="password" name="password" type="password" class="form-control" required></div>   <button class="btn btn-brand" type="submit">Sign in</button> </form></main></body></html> 